function wa(text){const tel=String(state.settings.whatsapp||'51945961938').replace(/\D/g,'');return 'https://wa.me/'+tel+'?text='+encodeURIComponent(text)}
function cartKey(){return state.account.userId?'yolyCart:'+state.account.userId:'yolyCart'}
