let cartQueue=Promise.resolve(), cloudVersion=0, pending=0;
const cleaned=items=>Object.fromEntries(Object.entries(items||{}).filter(([id,q])=>byId(id)&&Number.isInteger(q)&&q>0&&q<=99));
async function initAccountCart(){
 if(!state.account.userId)return;
 const key=cartKey(), guest=cleaned(read('yolyCart',{}));state.cart=cleaned(read(key,{}));
 try{
  const cloud=await api('/api/account/cart');cloudVersion=cloud.version;state.cart=cleaned(cloud.items);
  if(Object.keys(guest).length){
   const merged={...state.cart};for(const [id,q] of Object.entries(guest))merged[id]=Math.max(q,merged[id]||0);
   const result=await api('/api/account/cart',{items:merged,version:cloudVersion});cloudVersion=result.version;state.cart=cleaned(result.items);persist('yolyCart',{});
  }
 }catch{status('El carrito de tu cuenta tardó en responder. Puedes seguir usando este dispositivo.')}
}
function syncChanges(delta){
 if(!state.account.userId)return;
 pending++;cartQueue=cartQueue.then(async()=>{
  for(let attempt=0;attempt<3;attempt++){
   const cloud=await api('/api/account/cart'),items=cleaned(cloud.items);
   for(const [id,diff] of Object.entries(delta)){const n=Math.min(99,(items[id]||0)+diff);if(n<=0)delete items[id];else items[id]=n}
   try{const result=await api('/api/account/cart',{items,version:cloud.version});cloudVersion=result.version;if(pending===1){state.cart=cleaned(result.items);saveCart()}return}
   catch(err){if(err.status!==409||attempt===2)throw err}
  }
 }).catch(()=>status('El cambio quedó en este dispositivo. Revisa el carrito al abrir tu cuenta en otro equipo.')).finally(()=>pending--);
}
function setQty(id,n){const p=byId(id);if(!p||!Number.isInteger(n))return;const before=state.cart[id]||0;if(n<=0)delete state.cart[id];else if(available(p))state.cart[id]=Math.min(n,99);delete state.checkout.key;saveCart();syncChanges({[id]:(state.cart[id]||0)-before})}
