async function readExcel(file){if(/\.csv$/i.test(file.name)){const text=(await file.text()).replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0],sep=first.includes(';')?';':first.includes('\t')?'\t':',';let out=[],row=[],s='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){s+='"';i++}else quoted=!quoted}else if(!quoted&&c===sep){row.push(s);s=''}else if(!quoted&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;row.push(s);out.push(row);row=[];s=''}else s+=c}if(s||row.length){row.push(s);out.push(row)}return out}if(!/\.xlsx$/i.test(file.name))throw Error('Utiliza Excel .xlsx o CSV. Convierte .xls a .xlsx desde Excel.');const fs=await unzipXlsx(await file.arrayBuffer()),get=async p=>{if(!fs.has(p))throw Error('No se encuentra '+p);return xmlParse(await fs.get(p)())};const wb=await get('xl/workbook.xml'),sheets=tags(wb,'sheet'),sheet=sheets.find(s=>normalize(s.getAttribute('name'))==='productos')||sheets[0];if(!sheet)throw Error('Excel sin hojas.');const rid=sheet.getAttribute('r:id')||sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id'),rel=await get('xl/_rels/workbook.xml.rels'),target=tags(rel,'Relationship').find(x=>x.getAttribute('Id')===rid)?.getAttribute('Target');if(!target)throw Error('No se encuentra la hoja.');const path=target.startsWith('/')?target.slice(1):'xl/'+target.replace(/^\.\//,'');const d=await get(path),strings=fs.has('xl/sharedStrings.xml')?tags(await get('xl/sharedStrings.xml'),'si').map(x=>tags(x,'t').map(t=>t.textContent).join('')):[];return tags(d,'row').map(r=>{const a=[];for(const c of tags(r,'c')){const col=(c.getAttribute('r')||'A').match(/^[A-Z]+/i)?.[0]||'A';let idx=0;for(const char of col.toUpperCase())idx=idx*26+char.charCodeAt(0)-64;const type=c.getAttribute('t'),v=tags(c,'v')[0]?.textContent??'';a[idx-1]=type==='s'?strings[Number(v)]??'':type==='inlineStr'?tags(c,'t').map(t=>t.textContent).join(''):v}return a})}
