orders=function(r){const b=box(r,'Pedidos registrados');b.append(txt('Los pedidos nuevos reservan unidades al registrarse. Aceptar mantiene la reserva; cancelar libera las unidades; finalizar registra la venta sin descontar de nuevo.'));const filters=el('div',undefined,'office-filters'),f=options(['Todos','Pendiente','Confirmado','Entregado','Cancelado']);filters.append(f,btn('Actualizar pedidos',async()=>{try{await loadAdmin();adminRender()}catch(e){alert(e.message)}},'outline'));b.append(filters);const list=el('div');b.append(list);function draw(){list.replaceChildren();const rows=db.orders.filter(o=>f.value==='Todos'||o.status===f.value);if(!rows.length)list.append(txt('No hay pedidos en este estado.'));for(const o of rows){const c=box(list);c.append(el('strong',o.code+' · '+o.status),el('p',o.name+' · '+(o.phone||'')+' · '+money(o.total)),el('p',o.items.map(i=>i.qty+' × '+i.name).join(' · '),'demo-small'),txt([o.shipping,o.district,o.address,o.payment].filter(Boolean).join(' · ')));const active=['Pendiente','Confirmado'].includes(o.status);if(active)c.append(el('p',o.reserved===true?'Stock reservado · '+o.items.reduce((n,i)=>n+i.qty,0)+' unidades':'Pedido anterior sin reserva. Se reservará al aceptar.','office-tag '+(o.reserved===true?'ok':'warn')));if(o.status==='Pendiente')c.append(btn('Aceptar pedido',async()=>{if(o.status!=='Pendiente'||saving)return;try{if(o.reserved!==true){for(const i of o.items)if(privateStock(i.id)<i.qty)throw Error('Stock insuficiente: '+i.name);for(const i of o.items)move(db.products.find(p=>p.id===i.id),-i.qty,'Reserva '+o.code)}o.reserved=true;o.status='Confirmado';await saveDB();refreshCatalog();adminRender()}catch(e){alert(e.message)}},'primary'));if(o.status==='Confirmado')c.append(btn('Finalizar y emitir comprobante',async()=>{if(o.status!=='Confirmado'||saving)return;try{let sale=db.sales.find(s=>s.orderId===o.id);if(!sale)sale=recordSale(o.items,{orderId:o.id,orderCode:o.code,customer:o.name,phone:o.phone,channel:'Pedido web / WhatsApp',payment:o.payment,receiptType:'INTERNAL',issuer:issuerSnapshot()});o.status='Entregado';await saveDB();adminRender();showReceipt(sale)}catch(e){alert(e.message)}},'primary'));if(active)c.append(btn('Cancelar y liberar stock',async()=>{if(saving||!['Pendiente','Confirmado'].includes(o.status)||!confirm('¿Cancelar este pedido y liberar las unidades reservadas?'))return;try{if(o.reserved===true)for(const i of o.items){const p=db.products.find(p=>p.id===i.id);if(p)move(p,i.qty,'Cancelación '+o.code)}o.status='Cancelado';o.reserved=false;await saveDB();refreshCatalog();adminRender()}catch(e){alert(e.message)}},'outline'));if(o.status==='Entregado'){const sale=db.sales.find(s=>s.orderId===o.id);if(sale)c.append(btn('Ver comprobante',()=>showReceipt(sale),'outline'),btn('Enviar comprobante por WhatsApp',()=>sendReceiptWhatsApp(sale),'primary'));}}}f.onchange=draw;draw();};
// Los pedidos nuevos reservan inventario en el servidor al registrarse.
localApi=async function(path,body){if(path.startsWith('/api/reviews'))return {reviews:[]};if(path==='/api/ops/quote')return quote(body);if(path==='/api/ops/orders'){const existing=db.orders.find(o=>o.key===body.key);if(existing)return existing;const q=quote(body);if(Math.abs(q.total-body.expectedTotal)>.001)throw Error('El precio cambió. Revisa el pedido.');const o={...q,items:q.items.map(i=>({...i,ml:db.products.find(p=>p.id===i.id)?.ml})),id:uid(),code:'YM-'+Date.now().toString(36).toUpperCase()+'-'+uid().slice(0,4).toUpperCase(),key:body.key,name:body.name,phone:body.phone,shipping:body.shipping,payment:body.payment,district:body.district,address:body.address,reference:body.reference,notes:body.notes,status:'Pendiente',reserved:false,date:new Date().toISOString()};db.orders.unshift(o);await saveDB();return o}throw Error('Operación no disponible en modo local')};
done=function(o){const b=modal('Envía tu pedido por WhatsApp');b.append(el('h3',o.code),el('p','Tu pedido está registrado en YOLYMAX. Para enviarlo a YOLYMAX, abre WhatsApp y presiona Enviar. Las unidades quedan reservadas hasta que la tienda acepte o cancele tu pedido. La entrega y el pago se coordinan por WhatsApp.'),el('p','Total de productos: '+money(o.total)));const a=link('Abrir WhatsApp y enviar pedido ↗',wa(orderMessage(o)),'primary');a.target='_blank';a.rel='noopener noreferrer';b.append(a,el('p','El pedido no está pagado ni confirmado.','demo-small'),btn('Volver al catálogo',()=>{$('dialog').close();location.hash='#catalogo'}))};
// Clientes no ven cantidades, costos ni historial de terceros.
publicProducts=function(){return db.products.filter(p=>p.published!==false).map(({stock,cost,minStock,...p})=>({...p,photo:p.photo||PLACEHOLDER,available:stock>0}))};
refreshCatalog=function(){state.products=publicProducts();state.settings=db.settings;state.cart=Object.fromEntries(Object.entries(state.cart).filter(([id,q])=>byId(id)?.available&&q>0&&q<=99));saveCart();applyBrand();setupFilters();drawList()};
