function receiptNode(s){const issuer=s.issuer||issuerSnapshot(),b=el('article',undefined,'receipt-document'),head=el('div',undefined,'receipt-head');head.append(el('div','Y','receipt-logo'),el('h2',issuer.shop||issuer.name||'YOLYMAX'),el('small','PERFUMERÍA & BELLEZA'),el('h3','COMPROBANTE INTERNO DE VENTA'),el('strong',v3ReceiptCode(s)));b.append(head);if(issuer.name&&issuer.name!==issuer.shop)b.append(el('p',issuer.name));if(issuer.ruc)b.append(el('p','RUC declarado: '+issuer.ruc));if(issuer.address)b.append(el('p',issuer.address));const meta=el('div',undefined,'receipt-meta');for(const [k,v] of [['Fecha',dateLabel(s.date)],['Cliente',s.customer||'Cliente general'],['Documento',s.document||'—'],['Pago',s.payment||'Por coordinar'],['Canal',s.channel||'—'],['Referencia',s.orderCode||s.reference||'—']]){const row=el('div');row.append(el('small',k),el('strong',v));meta.append(row)}b.append(meta);makeTable(b,['Producto','Cant.','P. unit.','Importe'],s.items.map(i=>[[i.name,i.ml?i.ml+' ml':''].filter(Boolean).join(' · '),i.qty,money(i.price),money(i.total)]));const total=el('div',undefined,'receipt-total');total.append(el('span','TOTAL'),el('strong',money(s.total)));b.append(total,el('p','Gracias por tu compra.','receipt-thanks'),el('p',fiscalNotice,'receipt-legal'));return b}
function receiptHTML(s){const doc=receiptNode(s);return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+v3ReceiptCode(s).replace(/[^A-Za-z0-9-]/g,'')+'</title><style>body{font:14px Arial,sans-serif;color:#183c32;margin:20px;background:#fff}.receipt-document{max-width:600px;margin:auto;padding:24px;border:1px solid #ccd7ce;border-radius:8px}.receipt-head{text-align:center}.receipt-logo{display:inline-grid;place-items:center;width:46px;height:46px;border-radius:50%;background:#184438;color:#fff;font:30px Georgia}.receipt-head h2{font:28px Georgia;margin:10px 0 3px}.receipt-head h3{font-size:14px;letter-spacing:1px;margin-top:20px}.receipt-meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:20px 0}.receipt-meta small,.receipt-meta strong{display:block}.receipt-meta small{color:#666}.demo-table{width:100%;border-collapse:collapse}.demo-table th,.demo-table td{padding:9px 4px;border-bottom:1px solid #ddd;text-align:left;font-size:12px}.receipt-total{display:flex;justify-content:space-between;padding:15px;background:#edf4ee;margin-top:15px;font-size:20px}.receipt-legal{font-size:11px;text-align:center;border-top:1px dashed #aaa;padding-top:12px}.receipt-thanks{text-align:center}.printbtn{display:block;margin:20px auto;border:0;background:#184438;color:#fff;border-radius:7px;padding:12px 24px;cursor:pointer}@media print{body{margin:0}.receipt-document{border:0;padding:8mm}.printbtn{display:none}}</style></head><body>'+doc.outerHTML+'<button class="printbtn" onclick="window.print()">Imprimir / guardar PDF</button></body></html>'}
