function receiptText(s){return [s.issuer?.shop||db.settings.name||'YOLYMAX','COMPROBANTE INTERNO DE VENTA '+v3ReceiptCode(s),'Fecha: '+dateLabel(s.date),'Cliente: '+(s.customer||'Cliente general'),...(s.orderCode?['Pedido: '+s.orderCode]:[]),'',...s.items.map(i=>i.qty+' × '+i.name+(i.ml?' ('+i.ml+' ml)':'')+' | '+money(i.price)+' c/u | '+money(i.total)),'','TOTAL: '+money(s.total),'Medio de pago: '+(s.payment||'Por coordinar'),'Gracias por tu compra.',fiscalNotice].join('\n')}
