function whatsNumber(raw){const value=String(raw||'').trim(),digits=value.replace(/\D/g,'');if(!/^[+0-9 ()-]+$/.test(value))return '';if(/^9\d{8}$/.test(digits))return '51'+digits;if(/^519\d{8}$/.test(digits))return digits;if(value.startsWith('+')&&/^[1-9]\d{7,14}$/.test(digits))return digits;return ''}
