// Adaptador cloud: el único almacenamiento local público es carrito y favoritos.
let revision=null, saving=false;
async function request(path,body,method=body===undefined?'GET':'POST'){
 const res=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});
 let data;try{data=await res.json()}catch{throw Error('No se pudo conectar con el servidor ('+res.status+').')}
 if(!res.ok)throw Object.assign(Error(data.error||'Error de conexión'),{status:res.status});return data;
}
async function loadPublic(){const d=await request('/api/catalog');state.products=d.products;state.settings=d.settings;}
