async function cloudSave(){if(!adminUnlocked||revision===null)throw Error('Inicia sesión como administrador.');if(saving)throw Error('Hay una operación en curso.');saving=true;
 const wait=document.createElement('div');wait.textContent='Guardando en YOLYMAX…';wait.setAttribute('role','status');Object.assign(wait.style,{position:'fixed',inset:'0',zIndex:'2147483647',background:'#153b31e8',color:'white',display:'grid',placeItems:'center',fontSize:'1.2rem'});document.body.append(wait);
 try{for(const m of db.moves)if(!m.id)m.id=uid();const res=await request('/api/admin/state',{version:revision,state:db},'PUT');revision=res.version;for(const p of db.products)if(res.photos?.[p.id])p.photo=res.photos[p.id];return true;}catch(e){alert(e.message+' Se recargarán los datos del servidor para evitar inconsistencias.');location.reload();throw e;}finally{saving=false;wait.remove();}}
